<template>
<div class="login-wrapper">
  <!-- 顶部导航栏 -->
  <div class="login-topbar">
    <div class="login-logo" @click="$router.push('/login')">
      <img :src="logoUrl" class="logo-icon">
      <span>{{ $t('common.appTitle') }}</span>
    </div>
    <div style="flex: 1"></div>
    <!-- 深色模式 -->
    <div class="login-topbar-action" @click="toggleDark">
      <span style="font-size: 15px; margin-right: 4px;">{{ isDark ? '🌙' : '☀️' }}</span>
      <span style="font-size: 13px;">{{ isDark ? $t('header.darkMode') : $t('header.lightMode') }}</span>
    </div>
    <!-- 语言切换 -->
    <div class="login-topbar-action" @click="toggleLang">
      <span>{{ $t('header.langSwitch') }}</span>
    </div>
  </div>

  <!-- 右侧登录框 -->
  <div class="login-right">
    <el-form ref="form" :model="form" :rules="rules" class="login-card">
      <h2 class="login-title">{{ $t('login.title') }}</h2>
      <el-form-item prop="username">
        <el-input v-model="form.username" :placeholder="$t('login.usernamePlaceholder')" clearable>
          <template #prefix><el-icon><User /></el-icon></template>
        </el-input>
      </el-form-item>
      <el-form-item prop="password">
        <el-input v-model="form.password" :placeholder="$t('login.passwordPlaceholder')" clearable show-password>
          <template #prefix><el-icon><Lock /></el-icon></template>
        </el-input>
      </el-form-item>
      <el-form-item>
        <div style="display: flex; justify-content: space-between; align-items: center;">
          <el-input v-model="form.validCode" style="width: 60%;" :placeholder="$t('login.captchaPlaceholder')"></el-input>
          <ValidCode @input="createValidCode" style="flex-shrink: 0;"/>
        </div>
      </el-form-item>
      <el-form-item>
        <el-button type="primary" style="width: 100%" @click="login">{{ $t('login.loginBtn') }}</el-button>
      </el-form-item>
      <el-form-item>
        <el-button type="text" @click="$router.push('/register')">{{ $t('login.registerLink') }}</el-button>
      </el-form-item>
    </el-form>
  </div>
</div>
</template>

<script>
import request from "../utils/request";
import { ElMessage } from "element-plus";
import ValidCode from "../components/Validate";
import { useI18n } from 'vue-i18n';

export default {
  name: "Login",
  components: { ValidCode },
  data() {
    return {
      validCode: '',
      form: {},
      logoUrl: require("../assets/icon/login.png"),
      isDark: false,
      rules: {
        username: [{ required: true, message: '请输入用户名', trigger: 'blur' }],
        password: [{ required: true, message: '请输入密码', trigger: 'blur' }]
      }
    }
  },
  mounted() {
    document.documentElement.classList.remove('dark')
    this.isDark = false
  },
  methods: {
    createValidCode(data) { this.validCode = data },
    login() {
      this.$refs['form'].validate((valid) => {
        if (!valid) return
        if (!this.form.validCode) { ElMessage.error("请填写验证码"); return }
        if (this.form.validCode.toLowerCase() !== this.validCode.toLowerCase()) { ElMessage.error("验证码错误"); return }
        request.post("user/login", this.form).then(res => {
          if (res.code == 0) {
            ElMessage.success("登录成功")
            sessionStorage.setItem("user", JSON.stringify(res.data))
            this.$router.push("/dashboard")
          } else { ElMessage.error(res.msg) }
        })
      })
    },
    toggleDark() {
      this.isDark = !this.isDark
      if (this.isDark) {
        document.documentElement.classList.add('dark')
      } else {
        document.documentElement.classList.remove('dark')
      }
    },
    toggleLang() {
      const { locale } = useI18n()
      const next = locale.value === 'zh' ? 'en' : 'zh'
      locale.value = next
      localStorage.setItem('lang', next)
      location.reload()
    }
  }
}
</script>

